//! Deterministic test vectors for third-party FreeViewer viewers (OrientOS/Firn).
//!
//! `tests/orientos-vectors.json` is generated by `build()` below from fixed
//! inputs and checked by `vectors_match_committed_file`. Any change in
//! crypto.rs or proto.rs that alters a single byte of the wire format fails
//! this test, so the file is the contract.
//!
//! Regenerate (only after an intended, backward compatible change):
//!   FV_REGEN_VECTORS=1 cargo test vectors_match_committed_file

use serde_json::{json, Value};

use crate::crypto::{self, Cipher};
use crate::proto::{self, decode, encode, Msg, MonitorInfo, Tile};

/// 16x16 baseline JPEG (image crate 0.25, quality 80, 4:4:4, gradient) used
/// as the picture payload of the Frame/Tiles cipher vectors. Embedded as a
/// constant so the vector file does not depend on the encoder version.
const SAMPLE_JPEG_HEX: &str = include_str!("../tests/orientos-sample-jpeg.hex");

fn sample_jpeg() -> Vec<u8> {
    hex::decode(SAMPLE_JPEG_HEX.trim()).expect("sample jpeg hex")
}

fn seq_bytes(start: u8, n: usize) -> Vec<u8> {
    (0..n).map(|i| start.wrapping_add(i as u8)).collect()
}

fn arr32(v: Vec<u8>) -> [u8; 32] {
    let mut a = [0u8; 32];
    a.copy_from_slice(&v);
    a
}

fn arr16(v: Vec<u8>) -> [u8; 16] {
    let mut a = [0u8; 16];
    a.copy_from_slice(&v);
    a
}

fn h(b: &[u8]) -> String {
    hex::encode(b)
}

const DOC: &str = "\
FreeViewer test vectors for third-party viewers (OrientOS/Firn). TEST DATA ONLY - every secret below is public.
All binary values are lowercase hex strings. Generated and verified by src/vectors.rs (cargo test).
Sections:
  primitives  : standard known-answer tests (RFC 7748 X25519, RFC 5869 HKDF-SHA256, RFC 4231 HMAC-SHA256, AES-256-GCM zero key).
  handshake   : fixed viewer/host secrets + salt -> public keys, X25519 shared secret, session key, udp key, 4-digit code, handshake frames.
                session_key = HKDF-SHA256(ikm = shared, salt = salt(16), info = 'freeviewer-v1 session') -> 32 bytes.
                udp_key     = HKDF-SHA256(ikm = session_key, salt = none (zeros), info = 'freeviewer-v1 udp') -> 32 bytes.
                session_code = SHA-256('freeviewer-v1 code' || session_key)[0..4] as u32 big endian, mod 10000, zero padded to 4 digits.
                Frames: V->H 0x01||client_pub, H->V 0x02||host_pub||salt, V->H 0x03||proof, V->H 0x06||device_name(utf8), H->V 0x04 ok / 0x05 fail.
  argon2      : password_key = Argon2id(password utf8, salt(16)), version 0x13, m=19456 KiB, t=2, p=1, no secret, no associated data, 32 byte output
                (argon2 crate 0.5.3 Argon2::default()). proof = HMAC-SHA256(password_key, 'fv-auth' || client_pub || host_pub || salt). Uses client_pub/host_pub from 'handshake'.
  cipher      : data frame = 0x10 || nonce(12) || AES-256-GCM(key = session_key, nonce, plaintext, no AAD) = ciphertext || tag(16).
                nonce = direction byte (host->viewer = 1, viewer->host = 2) || 000000 || counter u64 big endian. Counter starts at 1 per direction, the receiver
                rejects counter <= last accepted. plaintext_hex = proto encoding of the message named in 'msg'.
  proto       : encode() bytes (hex) of every message type. Integers little endian; blobs/strings = u32 length + bytes. 'fields' is informative only.
                dir: 'H->V' host sends, 'V->H' viewer sends, 'both'. Blob contents in this section are fake bytes (not real JPEG/H.264).
  proto_reject: byte strings that decode() must reject (no crash, no message).
  sample_jpeg : the real 16x16 JPEG used inside the cipher vectors Frame/Tiles (decodes to 16x16 RGB).
Limits: max 4096 tiles per Tiles, max 8 MiB per Video, max 256 KiB clipboard text, max 512 KiB file chunk, max 32 monitors, max 64 resolutions.";

fn proto_case(name: &str, dir: &str, fields: Value, msg: &Msg) -> Value {
    let enc = encode(msg);
    // every vector must survive a decode/encode round trip
    let back = decode(&enc).expect("decode");
    assert_eq!(encode(&back), enc, "roundtrip {}", name);
    json!({ "name": name, "dir": dir, "fields": fields, "hex": h(&enc) })
}

