fn reject_vectors() -> Vec<Value> {
    let mut v = Vec::new();
    let mut add = |name: &str, bytes: Vec<u8>| {
        assert!(decode(&bytes).is_none(), "{} must be rejected", name);
        v.push(json!({ "name": name, "hex": h(&bytes) }));
    };
    add("empty", vec![]);
    add("unknown type 0xff", vec![0xFF]);
    add("Frame truncated", vec![0x21, 1, 2]);
    let full = encode(&Msg::Frame { width: 4, height: 4, jpeg: vec![1, 2, 3, 4] });
    add("Frame blob shorter than announced", full[..full.len() - 1].to_vec());
    let mut evil = vec![0x22];
    evil.extend_from_slice(&100u32.to_le_bytes());
    evil.extend_from_slice(&100u32.to_le_bytes());
    evil.extend_from_slice(&u32::MAX.to_le_bytes());
    add("Tiles count u32::MAX", evil);
    let mut evil = vec![0x22];
    evil.extend_from_slice(&100u32.to_le_bytes());
    evil.extend_from_slice(&100u32.to_le_bytes());
    evil.extend_from_slice(&4097u32.to_le_bytes());
    add("Tiles count 4097", evil);
    let mut evil = vec![0x37];
    evil.extend_from_slice(&(proto::MAX_CLIP as u32 + 1).to_le_bytes());
    add("Clipboard length over 256 KiB", evil);
    let mut evil = vec![0x25];
    evil.extend_from_slice(&1920u32.to_le_bytes());
    evil.extend_from_slice(&1080u32.to_le_bytes());
    evil.push(1);
    evil.extend_from_slice(&u32::MAX.to_le_bytes());
    add("Video length u32::MAX", evil);
    v
}

/// Seals `msgs` in order with a fresh Cipher and checks the peer can open them.
fn cipher_dir(key: &[u8; 32], is_host: bool, msgs: &[(&str, Msg)]) -> Vec<Value> {
    let mut tx = Cipher::new(key, is_host);
    let mut rx = Cipher::new(key, !is_host);
    let dir_byte: u8 = if is_host { 1 } else { 2 };
    let mut out = Vec::new();
    for (i, (name, msg)) in msgs.iter().enumerate() {
        let plain = encode(msg);
        let frame = tx.seal(&plain);
        let counter = (i + 1) as u64;
        assert_eq!(frame[0], 0x10);
        assert_eq!(frame[1], dir_byte);
        assert_eq!(&frame[2..5], &[0, 0, 0]);
        assert_eq!(&frame[5..13], &counter.to_be_bytes());
        assert_eq!(rx.open(&frame).expect("open"), plain, "open {}", name);
        out.push(json!({
            "msg": name,
            "dir": if is_host { "H->V" } else { "V->H" },
            "counter": counter,
            "nonce": h(&frame[1..13]),
            "plaintext_hex": h(&plain),
            "frame_hex": h(&frame),
        }));
    }
    out
}

/// Frame with a large counter, built by hand (Cipher counters start at 1).
fn big_counter_vector(key: &[u8; 32]) -> Value {
    use aes_gcm::aead::{Aead, KeyInit};
    use aes_gcm::{Aes256Gcm, Nonce};
    let counter: u64 = 0x0102_0304_0506_0708;
    let mut nonce = [0u8; 12];
    nonce[0] = 1;
    nonce[4..12].copy_from_slice(&counter.to_be_bytes());
    let plain = encode(&Msg::Ping { ts: 42 });
    let aead = Aes256Gcm::new_from_slice(key).unwrap();
    let ct = aead.encrypt(Nonce::from_slice(&nonce), plain.as_slice()).unwrap();
    let mut frame = vec![0x10];
    frame.extend_from_slice(&nonce);
    frame.extend_from_slice(&ct);
    // a fresh viewer-side cipher must accept it (counter > 0)
    let mut rx = Cipher::new(key, false);
    assert_eq!(rx.open(&frame).expect("open big counter"), plain);
    json!({
        "msg": "Ping (large counter 0x0102030405060708)",
        "dir": "H->V",
        "counter": counter,
        "nonce": h(&nonce),
        "plaintext_hex": h(&plain),
        "frame_hex": h(&frame),
    })
}

fn primitives() -> Value {
    use hmac::{Hmac, Mac};
    use sha2::Sha256;
    use x25519_dalek::{PublicKey, StaticSecret};

    // RFC 7748 section 6.1
    let a_priv = arr32(hex::decode("77076d0a7318a57d3c16c17251b26645df4c2f87ebc0992ab177fba51db92c2a").unwrap());
    let a_pub = PublicKey::from(&StaticSecret::from(a_priv)).to_bytes();
    assert_eq!(h(&a_pub), "8520f0098930a754748b7ddcb43ef75a0dbf3a0d26381af4eba4a98eaa9b4e6a");
    let b_pub = arr32(hex::decode("de9edb7d7b7dc1b4d35b61c2ece435373f8343c85b78674dadfc7e146f882b4f").unwrap());
    let shared = StaticSecret::from(a_priv).diffie_hellman(&PublicKey::from(b_pub));
    assert_eq!(h(shared.as_bytes()), "4a5d9d5ba4ce2de1728e3bf480350f25e07e21c947d19e3376f09b3c1e161742");

    // RFC 5869 test case 1
    let ikm = vec![0x0b; 22];
    let salt = seq_bytes(0, 13);
    let info = seq_bytes(0xf0, 10);
    let hk = hkdf::Hkdf::<Sha256>::new(Some(&salt), &ikm);
    let mut okm = [0u8; 42];
    hk.expand(&info, &mut okm).unwrap();
    assert_eq!(
        h(&okm),
        "3cb25f25faacd57a90434f64d0362f2a2d2d0a90cf1a5a4c5db02d56ecc4c5bf34007208d5b887185865"
    );

    // RFC 4231 test case 2
    let mut mac = <Hmac<Sha256> as Mac>::new_from_slice(b"Jefe").unwrap();
    mac.update(b"what do ya want for nothing?");
    let tag = mac.finalize().into_bytes();
    assert_eq!(h(&tag), "5bdcc146bf60754e6a042426089575c75a003f089d2739839dec58b964ec3843");

    // AES-256-GCM, zero key, zero nonce, 16 zero bytes (GCM spec test case 14)
    use aes_gcm::aead::{Aead, KeyInit};
    use aes_gcm::{Aes256Gcm, Nonce};
    let aead = Aes256Gcm::new_from_slice(&[0u8; 32]).unwrap();
    let ct = aead.encrypt(Nonce::from_slice(&[0u8; 12]), [0u8; 16].as_slice()).unwrap();
    assert_eq!(h(&ct), "cea7403d4d606b6e074ec5d3baf39d18d0d1c8a799996bf0265b98b5d48ab919");

    json!({
        "x25519_rfc7748": {
            "alice_private": h(&a_priv),
            "alice_public": h(&a_pub),
            "bob_public": h(&b_pub),
            "shared": h(shared.as_bytes()),
        },
        "hkdf_sha256_rfc5869_case1": {
            "ikm": h(&ikm), "salt": h(&salt), "info": h(&info), "length": 42, "okm": h(&okm),
        },
        "hmac_sha256_rfc4231_case2": {
            "key_ascii": "Jefe", "data_ascii": "what do ya want for nothing?", "mac": h(&tag),
        },
        "aes256gcm_zero": {
            "key": h(&[0u8; 32]), "nonce": h(&[0u8; 12]), "plaintext": h(&[0u8; 16]),
            "ciphertext_and_tag": h(&ct),
        },
    })
}

pub fn build() -> Value {
    // The Argon2 parameters must be the documented ones.
    let a = argon2::Argon2::default();
    let p = a.params();
    assert_eq!((p.m_cost(), p.t_cost(), p.p_cost()), (19456, 2, 1));
    assert_eq!(p.output_len(), None);
    assert_eq!(argon2::Algorithm::default(), argon2::Algorithm::Argon2id);
    assert_eq!(argon2::Version::default(), argon2::Version::V0x13);
    // Argon2::default() must behave exactly like the explicit parameter set
    let explicit = argon2::Argon2::new(
        argon2::Algorithm::Argon2id,
        argon2::Version::V0x13,
        argon2::Params::new(19456, 2, 1, Some(32)).unwrap(),
    );
    let (mut o1, mut o2) = ([0u8; 32], [0u8; 32]);
    a.hash_password_into(b"check", &[7u8; 16], &mut o1).unwrap();
    explicit.hash_password_into(b"check", &[7u8; 16], &mut o2).unwrap();
    assert_eq!(o1, o2);

    let client_secret = arr32(seq_bytes(0x01, 32));
    let host_secret = arr32(seq_bytes(0x21, 32));
    let salt = arr16(seq_bytes(0xA0, 16));
    let cs = x25519_dalek::StaticSecret::from(client_secret);
    let hs = x25519_dalek::StaticSecret::from(host_secret);
    let client_pub = x25519_dalek::PublicKey::from(&cs).to_bytes();
    let host_pub = x25519_dalek::PublicKey::from(&hs).to_bytes();
    let shared_v = cs.diffie_hellman(&x25519_dalek::PublicKey::from(host_pub));
    let shared_h = hs.diffie_hellman(&x25519_dalek::PublicKey::from(client_pub));
    assert_eq!(shared_v.as_bytes(), shared_h.as_bytes());
    let key_v = crypto::session_key(&cs, &host_pub, &salt);
    let key_h = crypto::session_key(&hs, &client_pub, &salt);
    assert_eq!(key_v, key_h);
    let key = key_v;
    let udp = crypto::udp_key(&key);
    let code = crypto::session_code(&key);

    let device = "Dell-OrientOS";
    let mut hello = vec![crypto::TAG_HELLO];
    hello.extend_from_slice(&client_pub);
    let mut hello_ack = vec![crypto::TAG_HELLO_ACK];
    hello_ack.extend_from_slice(&host_pub);
    hello_ack.extend_from_slice(&salt);
    let mut ask = vec![crypto::TAG_ASK];
    ask.extend_from_slice(device.as_bytes());

    let handshake = json!({
        "client_secret": h(&client_secret),
        "host_secret": h(&host_secret),
        "salt": h(&salt),
        "client_public": h(&client_pub),
        "host_public": h(&host_pub),
        "shared_secret": h(shared_v.as_bytes()),
        "session_key": h(&key),
        "udp_key": h(&udp),
        "session_code": code,
        "hello_frame_V_to_H": h(&hello),
        "hello_ack_frame_H_to_V": h(&hello_ack),
        "ask_device_name": device,
        "ask_frame_V_to_H": h(&ask),
        "ok_frame_H_to_V": h(&[crypto::TAG_OK]),
        "fail_frame_H_to_V": h(&[crypto::TAG_FAIL]),
        "relay_connect_json": "{\"t\":\"connect\",\"id\":\"123456789\"}",
    });

    // Argon2id + proof. Passwords are UTF-8; the umlaut one pins the byte encoding.
    let cases: [(&str, &str, [u8; 16]); 3] = [
        ("ascii", "hunter2", salt),
        ("umlaut", "Gr\u{00fc}\u{00df}e-P\u{00e4}ssw\u{00f6}rd", arr16(seq_bytes(0x10, 16))),
        ("long", "correct horse battery staple 0123456789", arr16(vec![0xEE; 16])),
    ];
    let mut argon = Vec::new();
    for (name, pw, s) in cases {
        let pw_key = crypto::password_key(pw, &s);
        let proof = crypto::auth_proof(&pw_key, &client_pub, &host_pub, &s);
        let mut frame = vec![crypto::TAG_PROOF];
        frame.extend_from_slice(&proof);
        assert!(crypto::proof_matches(&proof, &frame[1..]));
        argon.push(json!({
            "name": name,
            "password_utf8_hex": h(pw.as_bytes()),
            "password_note": pw,
            "salt": h(&s),
            "password_key": h(&pw_key),
            "proof": h(&proof),
            "proof_frame_V_to_H": h(&frame),
        }));
    }

    // Cipher vectors, both directions, real JPEG payloads for Frame/Tiles.
    let jpeg = sample_jpeg();
    let host_msgs: Vec<(&str, Msg)> = vec![
        ("ScreenInfo", Msg::ScreenInfo { width: 640, height: 480 }),
        (
            "Monitors",
            Msg::Monitors {
                active: 0,
                list: vec![MonitorInfo { name: "TESTHOST".to_string(), w: 640, h: 480, primary: true }],
            },
        ),
        ("Frame (sample_jpeg)", Msg::Frame { width: 16, height: 16, jpeg: jpeg.clone() }),
        (
            "Tiles (2 tiles, sample_jpeg)",
            Msg::Tiles {
                width: 64,
                height: 32,
                tiles: vec![
                    Tile { x: 0, y: 0, w: 16, h: 16, jpeg: jpeg.clone() },
                    Tile { x: 32, y: 16, w: 16, h: 16, jpeg: jpeg.clone() },
                ],
            },
        ),
        ("Cursor", Msg::Cursor { x: 5000, y: 5000, visible: true }),
        ("Clipboard", Msg::Clipboard { text: "hallo welt \u{00e4}\u{00f6}\u{00fc}".to_string() }),
        ("Pong", Msg::Pong { ts: 1_234_567_890 }),
    ];
    let viewer_msgs: Vec<(&str, Msg)> = vec![
        ("Caps h264=false", Msg::Caps { h264: false }),
        ("MouseMove", Msg::MouseMove { x: 5000, y: 2500 }),
        ("MouseButton left down", Msg::MouseButton { button: 0, down: true }),
        ("Key unicode U+00E4 down", Msg::Key { code: 228, named: false, down: true }),
        ("KeyVk Win (ext) down", Msg::KeyVk { vk: 0x5B, ext: true, down: true }),
        ("Clipboard", Msg::Clipboard { text: "hallo welt \u{00e4}\u{00f6}\u{00fc}".to_string() }),
        ("Ping", Msg::Ping { ts: 1_234_567_890 }),
    ];
    let mut cipher_h = cipher_dir(&key, true, &host_msgs);
    cipher_h.push(big_counter_vector(&key));
    let cipher_v = cipher_dir(&key, false, &viewer_msgs);

    json!({
        "_doc": DOC,
        "version": 1,
        "primitives": primitives(),
        "handshake": handshake,
        "argon2": {
            "params": { "algorithm": "argon2id", "version": "0x13", "m_cost_kib": 19456, "t_cost": 2, "p_cost": 1, "output_len": 32 },
            "cases": argon,
        },
        "cipher": {
            "key": h(&key),
            "host_to_viewer": cipher_h,
            "viewer_to_host": cipher_v,
        },
        "proto": proto_vectors(),
        "proto_reject": reject_vectors(),
        "sample_jpeg": h(&jpeg),
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    fn path() -> std::path::PathBuf {
        std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/orientos-vectors.json")
    }

    #[test]
    fn vectors_match_committed_file() {
        let v = build();
        if std::env::var("FV_REGEN_VECTORS").ok().as_deref() == Some("1") {
            let text = serde_json::to_string_pretty(&v).unwrap() + "\n";
            std::fs::write(path(), text).unwrap();
            return;
        }
        let text = std::fs::read_to_string(path()).expect("tests/orientos-vectors.json missing");
        let on_disk: Value = serde_json::from_str(&text).expect("vector file is valid json");
        assert_eq!(on_disk, v, "wire format changed: vector file is stale (FV_REGEN_VECTORS=1 to regenerate if intended)");
    }

    #[test]
    fn sample_jpeg_decodes() {
        let img = image::load_from_memory_with_format(&sample_jpeg(), image::ImageFormat::Jpeg)
            .expect("jpeg decodes");
        assert_eq!((img.width(), img.height()), (16, 16));
    }

    /// Helper that produced tests/orientos-sample-jpeg.hex:
    ///   cargo test print_sample_jpeg -- --ignored --nocapture
    #[test]
    #[ignore]
    fn print_sample_jpeg() {
        let mut rgb = Vec::new();
        for y in 0..16u32 {
            for x in 0..16u32 {
                rgb.extend_from_slice(&[(x * 16) as u8, (y * 16) as u8, 128]);
            }
        }
        let jpeg = crate::encoder::jpeg_rgb(&rgb, 16, 16, 80).unwrap();
        println!("{}", hex::encode(jpeg));
    }

    #[test]
    fn handshake_matches_wire_format_of_host_and_viewer() {
        // proof as the host computes it must equal the viewer's
        let v = build();
        let hs = &v["handshake"];
        assert_eq!(hs["session_code"].as_str().unwrap().len(), 4);
        assert_eq!(hs["session_key"].as_str().unwrap().len(), 64);
    }
}
